PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS EXOPLANETS.EXOPLANETS (
  _id VARCHAR(255),
  distance FLOAT,
  g FLOAT,
  orbital_period FLOAT,
  avg_temp FLOAT,
  date_added VARCHAR(255)
);
CREATE TABLE EXOPLANETS.EXOPLANETS_EXTENDED (
  _ID VARCHAR(255) NOT NULL,
  DISTANCE FLOAT,
  G FLOAT,
  ORBITAL_PERIOD FLOAT,
  AVG_TEMP FLOAT,
  DATE_ADDED TIMESTAMP NOT NULL,
  ECCENTRICITY FLOAT,
  ATMOSPHERE VARCHAR(255)
);
CREATE TABLE IF NOT EXISTS EXOPLANETS.HABITABLES (
  `_id` VARCHAR(255),
  `perihelion` FLOAT,
  `aphelion` FLOAT,
  `atmosphere` VARCHAR(255),
  `habitability` FLOAT,
  `min_temp` FLOAT,
  `max_temp` FLOAT,
  `date_added` VARCHAR(255)
);
CREATE TABLE IF NOT EXISTS EXOPLANETS.EXOPLANETS_COLUMNS (
  DATE VARCHAR(255),
  COLUMNS TEXT
);
COMMIT;
